const listAllCMSPages = `-- name: ListAllCMSPages :many
SELECT id, page_type_id, parent_id, slug, url_path, position, is_published, seo_noindex, published_at, data, metadata, private_metadata, created_at, updated_at, scheduled_at, base_path, experiment_key, tags, workflow_state, assigned_to, submitted_by, submitted_at, approved_by, approved_at FROM cms_pages ORDER BY url_path
`

func (q *Queries) ListAllCMSPages(ctx context.Context) ([]CmsPage, error) {
	rows, err := q.db.QueryContext(ctx, listAllCMSPages)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CmsPage{}
	for rows.Next() {
		var i CmsPage
		if err := rows.Scan(
			&i.ID,
			&i.PageTypeID,
			&i.ParentID,
			&i.Slug,
			&i.UrlPath,
			&i.Position,
			&i.IsPublished,
			&i.SeoNoindex,
			&i.PublishedAt,
			&i.Data,
			&i.Metadata,
			&i.PrivateMetadata,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ScheduledAt,
			&i.BasePath,
			&i.ExperimentKey,
			pq.Array(&i.Tags),
			&i.WorkflowState,
			&i.AssignedTo,
			&i.SubmittedBy,
			&i.SubmittedAt,
			&i.ApprovedBy,
			&i.ApprovedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

